InstructionDefinition.Payload:
@query=Select " 
    # Get logged in user
    $loggedOnUser = (Get-CimInstance Win32_ComputerSystem).UserName

    if (-not $loggedOnUser) {
        Return \"No logged in user detected.\"
        #exit 1
    }

    # Get user SID
    $userSID = (New-Object System.Security.Principal.NTAccount($loggedOnUser)).
                Translate([System.Security.Principal.SecurityIdentifier]).Value

    # Define registry paths using SID
    $prefPath   = \"Registry::HKEY_USERS\\$userSID\\Software\\Microsoft\\Office\\16.0\\Outlook\\Preferences\"
    $policyPath = \"Registry::HKEY_USERS\\$userSID\\Software\\Policies\\Microsoft\\Office\\16.0\\Outlook\\PST\"

    $useNewOutlookName  = \"UseNewOutlook\"
    $pstDisableGrowName = \"PSTDisableGrow\"

    try {
        $useNewOutlookValue = Get-ItemProperty -Path $prefPath -Name $useNewOutlookName -ErrorAction Stop |
                              Select-Object -ExpandProperty $useNewOutlookName

        if ($useNewOutlookValue -eq 0) {

            # Ensure PST policy key exists
            if (!(Test-Path $policyPath)) {
                New-Item -Path $policyPath -Force | Out-Null
            }

            # Check existing PSTDisableGrow value
            $existingValue = Get-ItemProperty -Path $policyPath -Name $pstDisableGrowName -ErrorAction SilentlyContinue |
                             Select-Object -ExpandProperty $pstDisableGrowName -ErrorAction SilentlyContinue

            if ($existingValue -eq 1) {
                Write-Output \"PSTDisableGrow already set to 1. No changes required.\"
                #exit 0
            }
            else {
                New-ItemProperty -Path $policyPath `
                                 -Name $pstDisableGrowName `
                                 -Value 1 `
                                 -PropertyType DWord `
                                 -Force | Out-Null

                Write-Output \"PSTDisableGrow set to 1 for user $loggedOnUser\"
                #exit 0
            }
        }
        else {
            Write-Output \"UseNewOutlook not equal to 0. No action taken.\"
            #exit 0
        }
    }
    catch {
        Write-Output \"Registry value not found or error occurred: $_\"
        #exit 1
    }

" As Text;
@Results = Scripting.RunText(Language: "PowerShell", Text: @query, ExecutionPolicy:"Override",InterpretAsJson:false);
